runner_source:
import hashlib,json,os,re,runpy,statistics,subprocess,sys,time
from pathlib import Path
ROOT=Path('/Users/chazu/dev/zig/birnam');sys.path.insert(0,str(ROOT/'scripts'))
PREFIX=Path('/tmp/birnam-74aj-landing-prefix');OUT=ROOT/'docs/measurements/74ak-closure-confirmation.json'
WORK=Path('/tmp/birnam-74ak-fixtures');WORK.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
numeric=runpy.run_path(str(ROOT/'scripts/counted-indices-production-timing.py'))
closure=runpy.run_path(str(ROOT/'scripts/closure-production-timing.py'))
loop=runpy.run_path(str(ROOT/'scripts/loop-production-timing.py'))
apps=runpy.run_path(str(ROOT/'scripts/recovery-applications.py'))
base=dict(UNBOXED_NUMERIC=0,LOOP_INVARIANTS=0,CLOSURE_ELISION=0,LITERAL_CALLEES=0,COUNTED_FRAME_INDICES=0,VIRTUAL_FIELDS=1,DISCARDED_CLONES=1)
configs={'numeric':dict(UNBOXED_NUMERIC=1),'loop':dict(LOOP_INVARIANTS=1),'closure':dict(CLOSURE_ELISION=1,LITERAL_CALLEES=1),'indices':dict(COUNTED_FRAME_INDICES=1),'combined':{k:1 for k in base}}
cases=[]
def add(name,group,src,kind,env=None,baseline=None):
 p=WORK/(name+'.birnam');p.write_text(src);cases.append(dict(name=name,group=group,fixture=str(p),sha256=sha(p),kind=kind,env=env or {},baseline=baseline or base))
for operations,shape,name in [(32,0,'hot'),(3,0,'short'),(32,2,'refused')]:
 for group in ('numeric','indices'):
  add(group+'-'+name,group,numeric['source'](operations,shape,1),'indices',dict(BIRNAM_NUMERIC_SHAPE=str(shape),BIRNAM_NUMERIC_BATCHES='5'))
for shape,name in [(0,'invariant'),(2,'changing'),(3,'independent')]:
 add('loop-'+name,'loop',loop['source'](16,shape),'loop',dict(BIRNAM_LOOP_BATCHES='5'))
for uses,shape,isnumeric,name in [(32,0,False,'private'),(32,0,True,'numeric'),(32,1,False,'escaping'),(32,3,False,'refused'),(1,0,False,'single')]:
 add('closure-'+name,'closure',closure['source'](uses,numeric=isnumeric),'closure',dict(BIRNAM_CLOSURE_SHAPE=str(shape),BIRNAM_CLOSURE_BATCHES='5'))
literal=closure['source'](32).replace('let closure := [| input];','let closure := [| 73];').replace('== input','= 73')
add('closure-literal','closure',literal,'closure',dict(BIRNAM_CLOSURE_SHAPE='0',BIRNAM_CLOSURE_BATCHES='5'))
pipeline=(ROOT/'bench/recovery-binding-pipeline.birnam').read_text()
insert='''[System load: "modules/time.birnam"];
[5 timesRepeat: [|
 let start := [Time monotonicMicros];
 [8 timesRepeat: [| [[ [run value: 5 value: 3] = 45152] ifTrue: [| nil] ifFalse: [| [OS exit: 82]]]]];
 let elapsed := [[Time monotonicMicros] - start];
 let gcStart := [Time monotonicMicros]; [System gc];
 let gcElapsed := [[Time monotonicMicros] - gcStart];
 [System println: ["bounded-sample-us " , [elapsed printString]]];
 [System println: ["bounded-gc-us " , [gcElapsed printString]]]
]];
'''
pipeline=pipeline.replace('let changed :=',insert+'let changed :=',1)
add('combined-pipeline','combined',pipeline,'pipeline',dict(BIRNAM_APPLICATION_PRECISE='1'))
configs['aggregates']=dict(VIRTUAL_FIELDS=1,DISCARDED_CLONES=1)
aggregatebase=dict(base,VIRTUAL_FIELDS=0,DISCARDED_CLONES=0)
add('aggregates-pipeline','aggregates',pipeline,'pipeline',dict(BIRNAM_APPLICATION_PRECISE='1'),aggregatebase)
for name in ('eval','collections','portable-collections','materialize-cold'):
 add('combined-'+name,'combined',(ROOT/'bench/native-tier-focus.birnam').read_text(),'focus',dict(NATIVE_TIER_FOCUS=name))
assert len(cases)==21
# One preplanned selected-combination confirmation; same cases, closure alone.
for case in cases: case['baseline']=base
configs={group:dict(CLOSURE_ELISION=1) for group in configs}
proof=json.loads((ROOT/'docs/measurements/74aj-landing-resumed.json').read_text());assert proof['status']=='passed'
for n,h in proof['sources'].items():assert sha(ROOT/n)==h,n
for n,h in proof['installed'].items():assert sha(PREFIX/n)==h,n
result=dict(status='running',qualified=False,policy='Selected combination confirmation: closure elimination only, with literal callees and all other optional defaults off. Three alternating pairs per fixed case; existing 74AJ semantic evidence reused. A consistent slowdown is median >5% with at least two pairs >5% for steady execution, execution plus GC, or total process time. These are pragmatic user-authorized comparisons, not host-qualified speed claims. No automatic retries.',started_at=time.time(),deadline=time.time()+1200,baseline=base,configurations=configs,cases=cases,rows=[],landing_sha256=sha(ROOT/'docs/measurements/74aj-landing-resumed.json'),production_sources=proof['sources'],installed=proof['installed'],runner_source=Path(__file__).read_text())
def save():OUT.write_text(json.dumps(result,indent=2)+'\n')
def samples(raw,prefix,count=5):
 xs=[int(x) for x in re.findall(r'^'+prefix+r' (\d+)$',raw,re.M)];assert len(xs)==count,(prefix,raw[-500:]);return xs
clean={k:v for k,v in os.environ.items() if not k.startswith(('BIRNAM_','DYLD_','NATIVE_TIER_','BENCH_HOST_'))}
try:
 save()
 for pair in range(3):
  ordered=cases[pair:]+cases[:pair]
  for case in ordered:
   for enabled in ((False,True) if pair%2==0 else (True,False)):
    assert time.time()<result['deadline'],'measurement time budget exhausted'
    flags=dict(case['baseline']);flags.update(configs[case['group']] if enabled else {})
    env=dict(clean,**case['env'],**{'BIRNAM_DEV_'+k:str(v) for k,v in flags.items()})
    start=time.monotonic();p=subprocess.run(['/usr/bin/time','-l',str(PREFIX/'bin/birnam'),case['fixture']],cwd=ROOT,env=env,capture_output=True,text=True,timeout=min(90,result['deadline']-time.time()))
    row=dict(pair=pair,case=case['name'],group=case['group'],enabled=enabled,flags=flags,exit_code=p.returncode,wall_seconds=time.monotonic()-start,stdout=p.stdout,stderr=p.stderr);result['rows'].append(row);save()
    assert p.returncode==0,(case['name'],p.stdout[-1500:],p.stderr[-500:])
    assert not any(x in p.stdout for x in ('EvaluationRejected','error(')),case['name']
    kind=case['kind']
    if kind=='indices':values=numeric['parsed'](p.stdout,5);execus=values['execution_us'];gcus=values['including_gc_us']
    elif kind=='loop':values=loop['parsed'](p.stdout,5);execus=values['execution_us'];gcus=values['including_gc_us']
    elif kind=='closure':
     assert p.stdout.splitlines().count('production-closure-ok')==1
     xs=samples(p.stdout,'production-sample-us');gs=samples(p.stdout,'production-gc-us');execus=sum(xs);gcus=execus+sum(gs)
    elif kind=='pipeline':
     assert p.stdout.splitlines().count('application-binding-pipeline passed')==1
     xs=samples(p.stdout,'bounded-sample-us');gs=samples(p.stdout,'bounded-gc-us');execus=sum(xs);gcus=execus+sum(gs)
    else:
     vals=apps['parse_output'](p.stdout,case['env']['NATIVE_TIER_FOCUS']);execus=sum(vals['sample-us']);gcus=execus
    row.update(execution_us=execus,including_gc_us=gcus,peak_rss_bytes=numeric['peak_rss'](p.stderr));save()
   print(pair,case['name'],'passed',flush=True)
 result['comparisons']=[]
 for case in cases:
  metrics={}
  for metric in ('execution_us','including_gc_us','wall_seconds','peak_rss_bytes'):
   changes=[]
   for pair in range(3):
    rs={r['enabled']:r for r in result['rows'] if r['case']==case['name'] and r['pair']==pair}
    changes.append(100*(rs[True][metric]/rs[False][metric]-1))
   metrics[metric]=dict(changes_percent=changes,median_change_percent=statistics.median(changes),consistent_slowdown=statistics.median(changes)>5 and sum(v>5 for v in changes)>=2)
  result['comparisons'].append(dict(case=case['name'],group=case['group'],metrics=metrics))
 for n,h in proof['sources'].items():assert sha(ROOT/n)==h,n
 for n,h in proof['installed'].items():assert sha(PREFIX/n)==h,n
 result['status']='passed'
except BaseException as e:result.update(status='failed',error=repr(e));raise
finally:result['finished_at']=time.time();save()
